import{_ as t,c as o,o as a,ag as r}from"./chunks/framework.DQvKz0xt.js";const v=JSON.parse('{"title":"钢笔工具概览 (Pen Tool Overview) - Rive 编辑器","description":"钢笔工具 (Pen tool) 允许你创建自定义矢量路径，以及向程序化路径添加额外的顶点。你可以通过观看视频或阅读下文来了解更多关于钢笔工具的信息。 钢笔工具允许你创建自定义矢量形状。你可以通过“创建工具 (Create Tools)”菜单找到它，或者使用快捷键 来激活。","frontmatter":{"title":"钢笔工具概览 (Pen Tool Overview) - Rive 编辑器","description":"钢笔工具 (Pen tool) 允许你创建自定义矢量路径，以及向程序化路径添加额外的顶点。你可以通过观看视频或阅读下文来了解更多关于钢笔工具的信息。 钢笔工具允许你创建自定义矢量形状。你可以通过“创建工具 (Create Tools)”菜单找到它，或者使用快捷键 来激活。","head":[["meta",{"name":"keywords","content":"Rive, Rive 中文文档, Rive 编辑器, 基础概念, 钢笔工具概览"}]]},"headers":[],"relativePath":"editor/fundamentals/pen-tool-overview.md","filePath":"editor/fundamentals/pen-tool-overview.md","lastUpdated":1774838907000}'),n={name:"editor/fundamentals/pen-tool-overview.md"};function s(l,e,i,p,d,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<p>基础概念</p><h1 id="钢笔工具概览-pen-tool-overview" tabindex="-1">钢笔工具概览 (Pen Tool Overview) <a class="header-anchor" href="#钢笔工具概览-pen-tool-overview" aria-label="Permalink to &quot;钢笔工具概览 (Pen Tool Overview)&quot;">​</a></h1><p>钢笔工具 (Pen tool) 允许你创建自定义矢量路径，以及向程序化路径添加额外的顶点。你可以通过观看视频或阅读下文来了解更多关于钢笔工具的信息。</p><h2 id="​-创建自定义形状" tabindex="-1"><a href="#creating-custom-shapes">​</a> 创建自定义形状 <a class="header-anchor" href="#​-创建自定义形状" aria-label="Permalink to &quot;[​](#creating-custom-shapes) 创建自定义形状&quot;">​</a></h2><p>钢笔工具允许你创建自定义矢量形状。你可以通过“创建工具 (Create Tools)”菜单找到它，或者使用快捷键 <code>P</code> 来激活。 在舞台上点击即可放置顶点。 <img src="https://help.rive.app/images/pen-tool-create.gif" alt="钢笔工具创建 Pn"> 点击并拖动可创建带有贝塞尔手柄（Bezier handles）的顶点。完成后，按下键盘上的 <code>Esc</code> 键。 <img src="https://help.rive.app/images/pen-tool-create-handless.gif" alt="钢笔工具手柄 Pn"></p><h2 id="​-路径与顶点快捷键" tabindex="-1"><a href="#path-&amp;-vertex-shortcuts">​</a> 路径与顶点快捷键 <a class="header-anchor" href="#​-路径与顶点快捷键" aria-label="Permalink to &quot;[​](#path-&amp;-vertex-shortcuts) 路径与顶点快捷键&quot;">​</a></h2><ul><li>按住 <strong>Alt (Opt)</strong>：在绘制路径时临时脱离钢笔工具。</li><li><strong>Ctrl+单击 (Cmd+单击)</strong>：在顶点上切换镜像手柄和直线手柄。</li><li>使用选择工具或钢笔工具，<strong>Ctrl+单击 (Cmd+单击)</strong> 顶点手柄：移除该手柄。</li><li>使用选择工具或钢笔工具，<strong>Alt+单击 (Opt+单击)</strong> 顶点手柄：分离（打断）该手柄。</li><li>使用钢笔工具，<strong>Alt+单击 (Opt+单击)</strong> 顶点：删除该顶点。</li><li><strong>Alt+拖动 (Option+拖动)</strong>：复制顶点。</li></ul><p><a href="/docs/editor/fundamentals/components">组件 (Components)</a><a href="/docs/editor/fundamentals/shapes-and-paths">形状与路径概览 (Shapes and Paths Overview)</a></p>',8)])])}const m=t(n,[["render",s]]);export{v as __pageData,m as default};
